Read the active sheet's cached values and build a first-match lookup from the seven master rows B2:H8 keyed by column B. For rows 12-14, match the cycle day in column B and write the corresponding C-H class values, leaving blanks for non-matching days. Save the workbook with only the answer region replaced by plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title if vals.active is not None else wb.active.title
ws = wb[sheet_name]
vws = vals[sheet_name]

def norm_key(x):
    if isinstance(x, bool):
        return x
    if isinstance(x, (int, float)):
        if isinstance(x, float) and x.is_integer():
            return int(x)
        return x
    if isinstance(x, str):
        s = x.strip()
        if not s:
            return None
        try:
            f = float(s)
            if f.is_integer():
                return int(f)
            return f
        except (ValueError, OverflowError):
            return s
    return x

def clean_value(x):
    if x is None:
        return None
    if isinstance(x, bool):
        return x
    if isinstance(x, float) and x.is_integer():
        return int(x)
    if isinstance(x, str):
        s = x.strip()
        return s if s else None
    return x

# Master cycle table is in rows 2-8, columns C-H, keyed by column B.
# Keep the first matching key to mirror the nested IF order.
master = {}
for r in range(2, 9):
    key = norm_key(vws.cell(row=r, column=2).value)
    if key is None or key in master:
        continue
    master[key] = [clean_value(vws.cell(row=r, column=c).value) for c in range(3, 9)]

# Answer region: C12:H14
for r in range(12, 15):
    key = norm_key(vws.cell(row=r, column=2).value)
    row_vals = master.get(key)
    if row_vals is None:
        row_vals = [None] * 6
    for c in range(3, 9):
        ws.cell(row=r, column=c).value = row_vals[c - 3]

print("sheet:", sheet_name)
print("master keys:", list(master.keys()))
for r in range(12, 15):
    print(r, [ws.cell(row=r, column=c).value for c in range(3, 9)])

wb.save(OUT)
